style.css:
/* ? ChatGPT Pink Pastel Theme ? */
/* Para Stylish / Stylus */

:root{
  --pink-bg: #fff7fb;
  --pink-sidebar: #fde7f3;
  --pink-card: #fff0f7;
  --pink-border: #f7cfe3;
  --pink-hover: #ffd9eb;
  --pink-text: #5c4b51;
  --pink-accent: #f5a9c6;
  --pink-accent-2: #e89ab8;
}

/* Fondo general */
body,
html{
  background: var(--pink-bg) !important;
  color: var(--pink-text) !important;
}

/* Sidebar izquierda */
aside{
  background: var(--pink-sidebar) !important;
  border-right: 1px solid var(--pink-border) !important;
}

/* Área principal */
main{
  background: var(--pink-bg) !important;
}

/* Mensajes */
[class*="message"],
[class*="conversation"]{
  background: var(--pink-card) !important;
  border-radius: 18px !important;
  border: 1px solid var(--pink-border) !important;
  padding: 10px !important;
}

/* Hover sidebar */
aside button:hover,
nav a:hover{
  background: var(--pink-hover) !important;
  border-radius: 12px !important;
}

/* Caja de escribir */
textarea{
  background: #fff !important;
  border: 2px solid var(--pink-border) !important;
  border-radius: 18px !important;
  color: var(--pink-text) !important;
}

/* Botón enviar */
button{
  border-radius: 14px !important;
}

/* Botón hover */
button:hover{
  background: var(--pink-hover) !important;
}

/* Links */
a{
  color: var(--pink-accent-2) !important;
}

/* Scrollbar cute */
::-webkit-scrollbar{
  width: 10px;
}

::-webkit-scrollbar-track{
  background: #ffeef7;
}

::-webkit-scrollbar-thumb{
  background: #f5b6d2;
  border-radius: 20px;
}

/* Código */
pre{
  background: #fff5fa !important;
  border: 1px solid var(--pink-border) !important;
  border-radius: 16px !important;
}

code{
  color: #c06188 !important;
}

/* Inputs */
input{
  background: #fff !important;
  border-radius: 12px !important;
  border: 1px solid var(--pink-border) !important;
}

/* Selección de texto */
::selection{
  background: #f8bfd7;
  color: #5c4b51;
}

/* Animación suave */
*{
  transition: all 0.2s ease-in-out;
}
